#!/usr/bin/env bash
# Builds the SINGLE founder-executable file scripts/release08/a0-founder-run.sh from the tested sources. Run from the repo root.
set -euo pipefail
D=scripts/release08; OUT=$D/a0-founder-run.sh
{
cat <<'HEAD'
#!/usr/bin/env bash
# BG-RELEASE08 A0 — ONE founder-executable file (generated by scripts/release08/build-a0-bundle.sh; do not edit). Usage: bash a0-founder-run.sh [run|shift|rollback]
# Runs in an ISOLATED bash (clean environment, no profile/rc files) and logs everything (never secrets) to ~/.bg-private/logs/.
set -euo pipefail
if [ -z "${BG_A0_ISOLATED:-}" ]; then
  umask 077; mkdir -p "$HOME/.bg-private/logs"; LOG="$HOME/.bg-private/logs/a0-$(date -u +%Y%m%dT%H%M%SZ).log"; : > "$LOG"
  echo "log file: $LOG"
  set +e; env -i HOME="$HOME" PATH="$PATH" TERM="${TERM:-dumb}" LANG=C.UTF-8 ${CLOUDSDK_CONFIG:+CLOUDSDK_CONFIG="$CLOUDSDK_CONFIG"} BG_A0_ISOLATED=1 BG_A0_LOG="$LOG" bash --noprofile --norc "$0" "$@" 2>&1 | tee -a "$LOG"; rc=${PIPESTATUS[0]}; exit "$rc"
fi
BG_A0_DIR=$(mktemp -d); chmod 700 "$BG_A0_DIR"; trap 'rm -rf "$BG_A0_DIR"' EXIT; export BG_A0_DIR
HEAD
for f in a0-prepare.sh a0-deploy.sh a0-smoke.sh; do
  m="BG_EMBED_END_$(echo "$f" | tr -c 'A-Za-z0-9\n' '_')"; grep -q "^$m\$" "$D/$f" && { echo "marker clash in $f" >&2; exit 1; }
  printf "cat > \"\$BG_A0_DIR/%s\" <<'%s'\n" "$f" "$m"; cat "$D/$f"; printf '%s\n' "$m"
done
cat "$D/a0-run.main.sh"
} > "$OUT"
bash -n "$OUT"; chmod +x "$OUT"; echo "wrote $OUT sha256=$(sha256sum "$OUT" | cut -d' ' -f1)"
